export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type FailedAt = Provider | "repository";
type AbortClassification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields & Readonly<{
  state: "queued";
}>;

type DispatchedShipment = ShipmentFields & Readonly<{
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}>;

type DeferredShipment = ShipmentFields & Readonly<{
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: readonly Rejection[];
}>;

type UnavailableShipment = ShipmentFields & Readonly<{
  state: "unavailable";
  rejections: readonly Rejection[];
}>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: AbortClassification;
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found" | "service_unavailable";
      };
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type CarrierConfirmation = Readonly<{
  provider: Provider;
  bookingId: string;
}>;

type CarrierOutcome =
  | Readonly<{ kind: "confirmed"; confirmation: CarrierConfirmation }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "throttled"; retryAtMs: number }>
  | Readonly<{ kind: "failed"; classification: Exclude<AbortClassification, "repository_failure"> }>;

type AttemptPlan = Readonly<{
  provider: Provider;
  rejections: readonly Rejection[];
}>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isNonBlankString(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }

  const rejections: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    rejections.push({ provider: item.provider, reason: item.reason });
  }
  return rejections;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || typeof value.shipmentId !== "string" || value.shipmentId.length === 0) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    typeof value.nowMs !== "number" ||
    !Number.isSafeInteger(value.nowMs) ||
    value.nowMs < 0 ||
    !isObject(value.recipient) ||
    !isNonBlankString(value.recipient.name) ||
    !isNonBlankString(value.recipient.postalAddress)
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    typeof value.id !== "string" ||
    value.id.length === 0 ||
    !isNonEmptyString(value.routeCode) ||
    typeof value.parcelGrams !== "number" ||
    !Number.isSafeInteger(value.parcelGrams) ||
    value.parcelGrams <= 0
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonEmptyString(value.bookingId) &&
    typeof value.dispatchedAtMs === "number" &&
    Number.isSafeInteger(value.dispatchedAtMs) &&
    value.dispatchedAtMs >= 0
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    typeof value.retryAtMs === "number" &&
    Number.isSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections !== undefined) {
      return { ...fields, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };

  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections.map((rejection) => ({ ...rejection })),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections.map((rejection) => ({ ...rejection })),
      };
  }
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): AbortBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map((rejection) => ({ ...rejection })),
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  body: AbortBody,
): void {
  dependencies.logger.info({
    shipmentId: body.shipmentId,
    action: "aborted",
    failedAt: body.failedAt,
    classification: body.classification,
    rejections: body.rejections.map((rejection) => ({ ...rejection })),
  });
}

function abortResponse(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: AbortClassification,
  rejections: readonly Rejection[],
): ServiceResponse {
  const body = abortBody(shipmentId, failedAt, classification, rejections);
  emitAbort(dependencies, body);
  return { status: 500, body };
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "failed", classification: "unknown_failure" };
  }
  if (error.code === "cannot_ship") {
    if (isRefusalReason(error.reason)) {
      return { kind: "refused", rejection: { provider: "atlas", reason: error.reason } };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  }
  if (error.code === "rate_limited") {
    if (
      typeof error.retryAtMs === "number" &&
      Number.isSafeInteger(error.retryAtMs) &&
      error.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: error.retryAtMs };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  }
  return { kind: "failed", classification: "unknown_failure" };
}

function classifyBeaconRejection(error: unknown, nowMs: number): CarrierOutcome {
  if (!isObject(error)) {
    return { kind: "failed", classification: "unknown_failure" };
  }
  if (error.type === "rejected") {
    if (isObject(error.details) && isRefusalReason(error.details.reason)) {
      return { kind: "refused", rejection: { provider: "beacon", reason: error.details.reason } };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  }
  if (error.type === "throttled") {
    if (
      isObject(error.details) &&
      typeof error.details.retryAtMs === "number" &&
      Number.isSafeInteger(error.details.retryAtMs) &&
      error.details.retryAtMs > nowMs
    ) {
      return { kind: "throttled", retryAtMs: error.details.retryAtMs };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  }
  return { kind: "failed", classification: "unknown_failure" };
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierOutcome> {
  if (provider === "atlas") {
    try {
      const confirmation = await dependencies.atlas.book(request);
      if (
        isObject(confirmation) &&
        typeof confirmation.bookingId === "string" &&
        confirmation.bookingId.length > 0
      ) {
        return {
          kind: "confirmed",
          confirmation: { provider: "atlas", bookingId: confirmation.bookingId },
        };
      }
      return { kind: "failed", classification: "invalid_provider_response" };
    } catch (error) {
      return classifyAtlasRejection(error, nowMs);
    }
  }

  try {
    const confirmation = await dependencies.beacon.reserve(request);
    if (
      isObject(confirmation) &&
      typeof confirmation.reference === "string" &&
      confirmation.reference.length > 0
    ) {
      return {
        kind: "confirmed",
        confirmation: { provider: "beacon", bookingId: confirmation.reference },
      };
    }
    return { kind: "failed", classification: "invalid_provider_response" };
  } catch (error) {
    return classifyBeaconRejection(error, nowMs);
  }
}

function hasCarrierRefusal(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

function nextPlanAfterRefusal(rejections: readonly Rejection[]): AttemptPlan | undefined {
  if (!hasCarrierRefusal(rejections, "atlas")) {
    return { provider: "atlas", rejections };
  }
  if (!hasCarrierRefusal(rejections, "beacon")) {
    return { provider: "beacon", rejections };
  }
  return undefined;
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  record: StoredShipment,
  event: Record<string, unknown>,
  failureRejections: readonly Rejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipment.id, record);
  } catch {
    return abortResponse(
      dependencies,
      shipment.id,
      "repository",
      "repository_failure",
      failureRejections,
    );
  }
  dependencies.logger.info(event);
  return undefined;
}

async function dispatchFromPlan(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  plan: AttemptPlan,
): Promise<ServiceResponse> {
  const request = providerRequest(shipment, command.recipient);
  const outcome = await attemptCarrier(dependencies, plan.provider, request, command.nowMs);

  switch (outcome.kind) {
    case "confirmed": {
      const dispatched: DispatchedShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "dispatched",
        provider: outcome.confirmation.provider,
        bookingId: outcome.confirmation.bookingId,
        dispatchedAtMs: command.nowMs,
      };
      const abort = await saveDecision(
        dependencies,
        shipment,
        dispatched,
        {
          shipmentId: shipment.id,
          action: "dispatched",
          provider: outcome.confirmation.provider,
        },
        plan.rejections,
      );
      if (abort) {
        return abort;
      }
      return { status: 200, body: publicShipment(dispatched) };
    }
    case "throttled": {
      const deferred: DeferredShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "deferred",
        nextProvider: plan.provider,
        retryAtMs: outcome.retryAtMs,
        rejections: plan.rejections.map((rejection) => ({ ...rejection })),
      };
      const abort = await saveDecision(
        dependencies,
        shipment,
        deferred,
        {
          shipmentId: shipment.id,
          action: "deferred",
          provider: plan.provider,
          retryAtMs: outcome.retryAtMs,
          rejections: deferred.rejections.map((rejection) => ({ ...rejection })),
        },
        plan.rejections,
      );
      if (abort) {
        return abort;
      }
      return { status: 202, body: publicShipment(deferred) };
    }
    case "failed":
      return abortResponse(
        dependencies,
        shipment.id,
        plan.provider,
        outcome.classification,
        plan.rejections,
      );
    case "refused": {
      const rejections = [...plan.rejections, outcome.rejection];
      const nextPlan = nextPlanAfterRefusal(rejections);
      if (nextPlan) {
        return dispatchFromPlan(dependencies, shipment, command, nextPlan);
      }

      const unavailable: UnavailableShipment = {
        schemaVersion: 1,
        id: shipment.id,
        routeCode: shipment.routeCode,
        parcelGrams: shipment.parcelGrams,
        state: "unavailable",
        rejections,
      };
      const abort = await saveDecision(
        dependencies,
        shipment,
        unavailable,
        {
          shipmentId: shipment.id,
          action: "unavailable",
          rejections: unavailable.rejections.map((rejection) => ({ ...rejection })),
        },
        rejections,
      );
      if (abort) {
        return abort;
      }
      return { status: 422, body: publicShipment(unavailable) };
    }
  }
}

function initialPlan(shipment: StoredShipment, nowMs: number): AttemptPlan | ServiceResponse {
  if (shipment.state === "dispatched") {
    return { status: 200, body: publicShipment(shipment) };
  }
  if (shipment.state === "unavailable") {
    return { status: 422, body: publicShipment(shipment) };
  }
  if (shipment.state === "deferred") {
    if (nowMs < shipment.retryAtMs) {
      return { status: 202, body: publicShipment(shipment) };
    }
    return {
      provider: shipment.nextProvider,
      rejections: shipment.rejections.map((rejection) => ({ ...rejection })),
    };
  }
  return { provider: "atlas", rejections: [] };
}

function isServiceResponse(value: AttemptPlan | ServiceResponse): value is ServiceResponse {
  return "status" in value;
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    const plan = initialPlan(shipment, command.nowMs);
    if (isServiceResponse(plan)) {
      return plan;
    }
    return dispatchFromPlan(dependencies, shipment, command, plan);
  }

  return { handle };
}
